echo -e "${MAGENTA}:: ${BOLD}Mission Center — программа для мониторинга состояния использования CPU, RAM, GPU, дисков, сети, процессов. Этот проект Лицензируется под GPL-3.0 или более поздняя версия. ${NC}"
