sudo pacman -S --noconfirm --needed stress  # Инструмент для стресс-тестирования вашей системы (ЦП, память, ввод-вывод, диски) ; https://archlinux.org/packages/extra/x86_64/stress/ ; https://github.com/resurrecting-open-source-projects/stress ; 2025-03-18 17:46 UTC
