# Примеры:
# В качестве примера работы stress авторы предлагают запустить:
# stress --cpu 8 --io 4 --vm 2 --vm-bytes 128M --timeout 10s
# Запустите 4 ЦП, 2 виртуальные памяти, 1 диск и 8 стрессоров в течение 2 минут и выведите измерения:
# stress-ng --cpu 4 --vm 2 --hdd 1 --fork 8 --timeout 2m --metrics
# Запустите Matrix Stressor на всех онлайн-процессорах на 60 секунд и измерьте температуру:
# stress-ng --matrix -1 --tz -t 60
# Запустите комбинацию из 4 стрессоров ввода-вывода и проверьте изменения в метаданных SMART диска:
# sudo stress-ng --iomix 4 --smart -t 30s
# Тестирование системных вызовов с использованием VDSO:
# stress-ng --vdso 1 -t 5 --metrics
# Сгенерируйте и измерьте пропуски ветвлений с помощью метрик производительности:
# sudo stress-ng --branch 1 --perf -t 10 | grep Branch
# Запустите перестановки факторов стресса ввода-вывода в файловой системе ZFS, за исключением фактора стресса rawdev с проверкой ошибок журнала ядра:
# stress-ng --class io --permute 0 -x rawdev -t 1m --vmstat 1 --klog-check  --temp-path /zfs-pool/test
# Только для x86: измерение мощности с помощью интерфейсов RAPL на 8 параллельных 3D-матричных стрессорах с включённой верификацией. Обратите внимание, что для чтения RAPL требуются права root.
# sudo stress-ng --matrix-3d 8 --matrix-3d-size 512 --rapl -t 10 --verify
