############ baobab ##############
sudo pacman -S --noconfirm --needed baobab  # Приложения для мониторинга дисков - Графический анализатор дерева каталогов ; https://wiki.gnome.org/Apps/DiskUsageAnalyzer ; https://archlinux.org/packages/extra/x86_64/baobab/ ; https://gitlab.gnome.org/GNOME/baobab/ ; https://help.gnome.org/users/baobab/stable/ ; https://github.com/GNOME/baobab ; 2025-07-24 19:54 UTC
  echo ""
  echo " Посмотрите информацию о версии (baobab) "
sudo pacman -Q baobab  #  Показать версию приложения
