# Installing utilities (packages) for Thorough cleaning of the Archlinux system
echo ""
echo -e "${YELLOW}==> Примечание! ${BOLD} *Для тщательной очистки системы Arch Linux можно использовать как команды в терминале, так и программы. Накопление мусора (временных файлов, кэша, неиспользуемых пакетов) со временем может замедлять производительность системы. Как и многие другие дистрибутивы Linux, Arch использует пакетный менеджер для установки и управления приложениями. При обновлении пакетов кэш пакетного менеджера также может накапливаться, и его можно удалить, чтобы освободить место на диске. *Важно понимать, что очистка системы может привести к потере данных, поэтому перед выполнением любой команды необходимо убедиться, что данные, которые вы хотите сохранить, будут безопасны. ${NC}"
sleep 15
clear
echo ""
echo -e "${BLUE}:: ${NC}Установить BleachBit (bleachbit) — Чистка мусора в системе?"
echo -e "${YELLOW}==> Примечание! ${BOLD} *В Bleachbit помимо простой очистки, приложение имеет в своём арсенале и несколько других интересных возможностей... Это особенно полезно, когда Вы делитесь компьютером с другими людьми, и любой может найти вашу личную информацию. ${NC}"
echo -e "${MAGENTA}:: ${BOLD}BleachBit — мощное, но простое в использовании, Python / GTK+ приложение для быстрой комплексной очистки системы, безвозвратного удаления файлов, зачистки свободного дискового пространства, очищения виртуальной и физической памяти (стирает своп и незанятую память). BleachBit уничтожает временные файлы (кеш) браузеров (Firefox, Epiphany, Google Chrome, Opera, Safari, и.т.д...), историю посещений, cookles, список закачанных файлов, базу данных имён пользователей и паролей, а также список сайтов, для которых не нужно сохранять пароли, неверные ссылки и прочее... BleachBit может устранить фрагментацию базы данных, для уменьшения занимаемого пространства и увеличения скорости без удаления данных. Удаляет ненужные файлы оставшиеся после работы множества популярных и приложений, таких как: кеш APT и Yum, Bash (консольная история пользователя), Beagle, GIMP, Google Earth, FileZilla, aMule, Java, KDE, OpenOffice.org, d4x, Skype, Links2, Xine, VIM, XChat и др... В списке около 70(ти) приложений. Можно использовать как GUI так и консольный вариант приложения, а при выполнении потенциально не безопасных действий требуется их подтверждение. Этот проект Лицензируется под GPL-3.0 или более поздняя версия. ${NC}"
echo " Домашняя страница: https://www.bleachbit.org/ ; (https://github.com/bleachbit/bleachbit ; https://sourceforge.net/projects/bleachbit/ ; https://archlinux.org/packages/extra/any/bleachbit/). "
echo -e "${BLUE}:: ${NC}Функции: Кроме средств удаления временных файлов BleachBit поможет удалить все неиспользуемые локализации (файлы для ненужных языков), испорченные вхождения меню приложений и ассоциации файлов, файлы резервной копии, DS_Store, Thumbs.db файлы и лог-файлы (старые системные журналы). Лог-файлы (логи/журналы отладки/системные журналы) это самые обычные текстовые файлы в которых записываются ошибки при работе приложений. Обычному пользователю они вряд ли будут нужны, а вот их размеры могут достигать сотни мегабайт (это происходит когда приложение долгое время работает неправильно). Bleachbit будет удалять только неиспользуемые файлы и логи, разработчики позаботились о том чтобы приложение не удалило никаких важных системных файлов. А удалив множество ненужных лог-файлов будет освобождено место на жестком диске. BleachBit так же включает в себя средства безвозвратного, 100% удаления файлов с диска (многократного форматирования) без возможности их восстановления. Так же, BleachBit может произвести и зачистку свободного дискового пространства, многократным его форматированием, для увеличения конфиденциальности. Это довольно долгая процедура и при этом, дисковая утилита может выдавать сообщения о уменьшении свободного места. BleachBit имеет возможность предварительного просмотра всех намеченных действий, а после завершения возможен просмотр выполненных процедур с выводом размера освобождённого пространства. "
echo -e "${CYAN}:: ${NC}Интерфейс: Окно программы разделено на две части. Слева отображается древовидный список того, что можно очистить. При клике на любой из пунктов справа отображается информация о том, что именно будет удалено. После выбора пунктов для удаления можно нажать кнопку Предпросмотр (Preview) и посмотреть какие файлы будут удалены, сколько файлов и их размер. Чтобы начать процесс удаления нужно нажать кнопку Очистка (Clean)."
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
