clear
echo ""
echo -e "${BLUE}:: ${NC}Установить TLPUI (tlpui) — Пользовательский интерфейс для TLP (tlp)?"
echo -e "${YELLOW}==> Примечание! ${BOLD} *TLPUI для работы требует прав администратора (root), помечаются все изменения внесённые в параметры "по умолчанию", для сохранения внесённых изменений требуется подтверждение, после внесения изменений необходимо "Перезагрузить настройки" (tlp-stat), можно просмотреть простую или полную версию статистики. ${NC}"
echo -e "${MAGENTA}:: ${BOLD}TLPUI — интуитивно понятный Python / GTK графический интерфейс для консольной утилиты TLP. Скрипты Python в этом проекте генерируют GTK-UI для лёгкого изменения файлов конфигурации TLP. Его цель — защитить пользователей от установки неподходящих конфигураций и предоставить базовый обзор всех допустимых значений конфигурации. Из интерфейса TLPUI можно легко скорректировать настройки TLP (/etc/default/tlp), при этом предусмотрена защита от выставления пользователем неправильных и/или ошибочных параметров, предоставляя только набор допустимых значений конфигурации для имеющегося оборудования, для большинства параметров имеются краткие описания. В зависимости от источника питания (батарея или от сети) TLPUI позволяет задать режим работы ноутбука, частоту процессора (включая "turbo boost" / "turbo core"), активировать планировщик с малым потреблением энергии для многоядерных процессоров или с hyper-threading, включить расширенное управление питанием жёстких дисков и продолжительностью вращения шпинделя. Поддерживается установка агрессивного управление питанием SATA (ALPM), управление питанием PCI Express (PCIe ASPM) и PCI(e) устройств в режиме реального времени, управление питанием Radeon KMS (но не fglrx), автоматическая приостановка работы USB (autosuspend) с поддержкой чёрных списков устройств, режим экономии питания Wi-Fi и выключение питания оптических приводов. Этот проект Лицензируется под GPL-2.0 или более поздняя версия. ${NC}"
echo " Домашняя страница: https://github.com/d4nj1/TLPUI ; (https://github.com/chinf/psensor ; https://aur.archlinux.org/packages/tlpui). "
echo -e "${BLUE}:: ${NC}Основные возможности утилиты TLPUI (tlpui) включают: графический интерфейс — обеспечивает удобный доступ к настройкам tlp без необходимости редактирования конфигурационных файлов вручную; настройку параметров процессора — позволяет регулировать параметры энергосбережения и производительности процессора; управление жесткими дисками — настройка параметров энергопотребления и производительности для жестких дисков; конфигурацию беспроводных устройств — позволяет настраивать параметры энергопотребления для Wi-Fi и других беспроводных компонентов; управление сетевыми устройствами — настройка параметров энергосбережения для сетевых карт и интерфейсов; оптимизацию графических устройств— позволяет регулировать энергопотребление графических карт; настройку звуковых устройств — возможность управления параметрами энергопотребления звуковых карт; гибкость конфигурации — возможность создания и применения различных настроек для различных сценариев использования; мониторинг состояния — предоставляет информацию о текущем состоянии энергопотребления и параметрах системы. "
echo -e "${CYAN}:: ${NC}Прежде чем запустить интерфейс tlpui, сначала установите необходимые пакеты. Пакеты tlp доступны в официальном репозитории: tlp – пакет для оптимизации управления энергопотреблением; tlp-rdw (необязательный) – пакет для управления беспроводными устройствами в tlp; tlpui – графический интерфейс утилиты командной строки tlp. После установки запуск программы доступен из «Главного меню» — «Параметры» — «TLP UI». Для запуска tlpui через терминал введите команду: tlpui . Для смены языка приложения перейдите в меню «Language» и в выпадающем списке выберите необходимый язык (например русский). В зависимости от источника питания (батарея или от сети) применяются настройки: Режим ноутбука и таймауты грязных буферов (dirty buffer). Частота процессора, включая "turbo boost" / "turbo core". Планировщик с малым потреблением энергии для многоядерных процессоров или с hyper-threading. Расширенное управление питанием жёстких дисков и продолжительностью вращения шпинделя. Агрессивное управление питанием SATA (ALPM). Управление питанием PCI Express (PCIe ASPM). Управление питанием PCI(e) устройств в режиме реального времени. Управление питанием Radeon KMS, но не fglrx. Wi-Fi режимы экономии питания. Выключение питания оптических приводов. "
echo -e "${CYAN}:: ${NC}Установка TLPUI (tlpui) проходит через сборку из исходников, которые устанавливаются из 'AUR' через 'yay' в зависимости от вашего выбора. Также в сценарии (скрипта) прописана установка с помощью git clone, PKGBUILD, makepkg - скачивается с сайта 'Arch Linux' (https://aur.archlinux.org/tlpui.git), (https://aur.archlinux.org/packages/tlpui) - собирается и устанавливается. Но эта функция закомментирована # , если нужно раскомментируйте или воспользуйтесь сценарием (скрипта) как шпаргалкой ! "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
echo ""
while
echo " Действия ввода, выполняется сразу после нажатия клавиши "
    read -n1 -p "
    1 - *Да установить,     0 - НЕТ - Пропустить установку: " in_tlpui  # sends right after the keypress; # отправляет сразу после нажатия клавиши
    echo ''
    [[ "$in_tlpui" =~ [^10] ]]
do
    :
done
if [[ $in_tlpui == 0 ]]; then
echo ""
echo " Установка утилит (пакетов) пропущена "
elif [[ $in_tlpui == 1 ]]; then
  echo ""
